/*B"H — one panel, one clear control */
.panel-topbar {
  min-height: 48px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 0 12px;
  border-bottom: 1px solid var(--ai-border);
  background:
    linear-gradient(90deg, rgba(31,111,235,.34), rgba(47,240,160,.13)),
    radial-gradient(circle at 0 0, rgba(126,212,255,.20), transparent 42%);
  user-select: none;
  cursor: default;
  overflow: hidden;
}
.panel-title {
  font-weight: 950;
  letter-spacing: .012em;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-shadow: 0 1px 16px rgba(126,212,255,.18);
}
.panel-actions {
  display: inline-flex;
  gap: 6px;
  flex: 0 0 auto;
  padding: 3px;
  border-radius: 16px;
  background: rgba(2,6,23,.34);
  border: 1px solid rgba(125,211,252,.10);
}
.panel-actions button {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  border: 1px solid var(--ai-border);
  background: rgba(2,8,16,.88);
  color: var(--ai-text);
  cursor: pointer;
  line-height: 1;
  font-weight: 900;
}
.panel-actions button:hover {
  transform: translateY(-1px);
  border-color: var(--ai-border-hot);
  background: rgba(10, 28, 48, .94);
  box-shadow: 0 0 0 3px rgba(126,212,255,.08);
}

.sidebar.is-panel-fullscreen,
.automation-panel.is-panel-fullscreen {
  position: fixed !important;
  inset: 14px !important;
  width: auto !important;
  height: auto !important;
  max-width: none !important;
  max-height: none !important;
  z-index: 2147482500;
  border-radius: 28px;
  background: rgba(2,6,23,.96);
  box-shadow: 0 34px 130px rgba(0,0,0,.76), 0 0 0 1px rgba(34,211,238,.28), 0 0 120px rgba(168,85,247,.16);
}

.sidebar.is-panel-fullscreen > :not(.panel-topbar),
.automation-panel.is-panel-fullscreen > :not(.panel-topbar) {
  display: block !important;
  min-height: 0;
  overflow: auto;
}

.automation-panel.is-panel-fullscreen .automation-panel-content,
.sidebar.is-panel-fullscreen .conversation-list {
  height: calc(100vh - 92px);
  overflow: auto;
}

body.has-panel-fullscreen .main:not(.is-panel-fullscreen),
body.has-panel-fullscreen .sidebar:not(.is-panel-fullscreen),
body.has-panel-fullscreen .automation-panel:not(.is-panel-fullscreen) {
  filter: blur(1px) brightness(.58);
}
